      titulo: 'Bicicleta',
      lanceInicial: 100,
      incrementoMinimo: 10,
      prorrogacaoSegundos: 5,
      status: 'ABERTO',
      maiorLance: null,
      totalLances: 0,
      encerraEm: expect.any(String),
      vencedor: null,
    });
  });

