// Documentação: docs/arquitetura.md (seção "Camadas e dependências permitidas").
/** @type {import('dependency-cruiser').IConfiguration} */
module.exports = {
  forbidden: [
    {
      name: 'sem-ciclos',
      severity: 'error',
      comment:
        'Dependências circulares impedem entender quem reage a quem. Extraia o que é compartilhado para dominio/tipos.ts.',
      from: {},
      to: { circular: true },
    },
    {
      name: 'dominio-puro',
      severity: 'error',
      comment:
        'A camada dominio/ só contém tipos e funções puras (decidir/evoluir/validar). Não pode importar NestJS, RxJS, Node nem as camadas aplicacao/ e http/.',
      from: { path: '^src/[^/]+/dominio/' },
      to: {
        pathNot: '^src/[^/]+/dominio/',
      },
    },
    {
      name: 'aplicacao-nao-conhece-http',
      severity: 'error',
      comment: 'A camada aplicacao/ (fluxos RxJS) não pode depender da camada http/ (controllers).',
      from: { path: '^src/[^/]+/aplicacao/' },
      to: { path: '^src/[^/]+/http/' },
    },
    {
      name: 'emissor-nao-conhece-observadores',
      severity: 'error',
      comment:
        'O módulo de leilões só publica eventos; quem reage (notificações...) assina o fluxo. Leilões nunca importam notificacoes/.',
      from: { path: '^src/leiloes/' },
      to: { path: '^src/notificacoes/' },
    },
    {
      name: 'observador-usa-api-publica',
      severity: 'error',
      comment:
        'Outros módulos só podem usar de leiloes/ o serviço de aplicação (fluxos) e os tipos de domínio, nunca os controllers.',
      from: { path: '^src/(?!leiloes/)[^/]+/' },
      to: { path: '^src/leiloes/http/' },
    },
    {
      name: 'sem-event-emitter',
      severity: 'error',
      comment: 'Eventos são modelados com RxJS. Não use EventEmitter (node:events) nem @nestjs/event-emitter.',
      from: { path: '^src/' },
      to: { path: '(^|/)node_modules/@nestjs/event-emitter/|^events$|^node:events$' },
    },
  ],
  options: {
    doNotFollow: { path: 'node_modules' },
    exclude: { path: '\\.(spec|e2e-spec)\\.ts$' },
    tsPreCompilationDeps: true,
    tsConfig: { fileName: 'tsconfig.json' },
    enhancedResolveOptions: {
      extensions: ['.ts', '.js', '.json'],
    },
  },
};
#!/usr/bin/env bash
# Validação completa do projeto (parte do harness).  Uso: npm run validate
# Roda todas as etapas (mesmo que uma falhe) e termina com "VALIDAÇÃO OK" ou "VALIDAÇÃO FALHOU".
set -uo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."
source scripts/lib/node.sh
source scripts/lib/registrar.sh
export NO_COLOR=1 FORCE_COLOR=0 CI=1

ETAPAS=(
  "tipos|npx tsc --noEmit -p tsconfig.json"
  "lint|npx oxlint --type-aware src/ test/"
  "regras-reativas|node scripts/verificar-reatividade.mjs"
  "dependencias|npx depcruise src --config .dependency-cruiser.cjs --output-type err"
  "estrutura|node scripts/verificar-estrutura.mjs"
  "testes-unitarios|npx vitest run --passWithNoTests"
  "testes-contrato|npx vitest run --config vitest.config.e2e.ts"
)

mkdir -p .harness/validacao
falhas=()
for etapa in "${ETAPAS[@]}"; do
  nome="${etapa%%|*}"; comando="${etapa#*|}"
  inicio=$(date +%s)
  if bash -c "$comando" > ".harness/validacao/$nome.log" 2>&1; then
    printf '✔ %-17s %3ss\n' "$nome" "$(( $(date +%s) - inicio ))"
  else
    printf '✖ %-17s %3ss\n' "$nome" "$(( $(date +%s) - inicio ))"
    falhas+=("$nome")
    echo "──── saída de '$nome' (últimas 80 linhas; completa em .harness/validacao/$nome.log) ────"
    tail -n 80 ".harness/validacao/$nome.log" | sed 's/\x1b\[[0-9;]*m//g'
    echo "────"
  fi
done

if [ ${#falhas[@]} -eq 0 ]; then
  registrar "validate ok"
  echo "VALIDAÇÃO OK"
  exit 0
fi
