  executar(comando: ComandoLeilao): Observable<ProcessamentoDeEntrada> {
    return defer(() => {
      const entrada: Entrada = { id: randomUUID(), comando, instante: Date.now() };
      const resultado$ = this.processamento$.pipe(first((p) => p.entradaId === entrada.id));
      const envio$ = defer(() => {
        this.entrada$.next(entrada);
